/**
 * The Workbench Named Graphs page count ({@code GRAPH ?g { ?s ?p ?o } GROUP BY ?g}) is answered from the exact
 * per-context statement counts in the LMDB context catalog whenever that catalog is exact for the queried plane(s):
 * O(#contexts), no adjacency page sweep. When the opposite statement plane is populated the catalog combines both
 * planes and is no longer exact for one of them, so the census must fall back to its page-header sweep.
 */
@ResourceLock(Resources.SYSTEM_PROPERTIES)
class LmdbNativeCensusContextCatalogTest {

	private static final String EX = "urn:census-catalog:";
	private static final String NATIVE = "rdf4j.lmdb.nativeQueryEngine.enabled";
	private static final String CATALOG = "source=CONTEXT_CATALOG";
	private static final String SWEEP = "source=ADJACENCY_CENSUS";
	private static final String NO_DECODES = "decoded=root:0,neighbor:0,context:0";
	private static final String GRAPH_COUNTS = "SELECT ?context (COUNT(*) AS ?statements) "
			+ "WHERE { GRAPH ?context { ?s ?p ?o } } GROUP BY ?context";
	private static final String GRAPH_SUBJECT_COUNTS = "SELECT ?context (COUNT(?s) AS ?statements) "
			+ "WHERE { GRAPH ?context { ?s ?p ?o } } GROUP BY ?context";
	private static final String GRAPH_TOTAL = "SELECT (COUNT(*) AS ?statements) WHERE { GRAPH ?context { ?s ?p ?o } }";
	private static final String NAMED_RESTRICTED = "SELECT ?context (COUNT(*) AS ?statements) FROM NAMED <" + EX
			+ "g2> WHERE { GRAPH ?context { ?s ?p ?o } } GROUP BY ?context";

	@TempDir
	File dataDir;
	private final Map<String, String> savedProperties = new HashMap<>();
	private SailRepository repository;
	private LmdbStore store;

	@BeforeEach
	void saveProperties() {
		savedProperties.put(NATIVE, System.getProperty(NATIVE));
		System.setProperty(NATIVE, "true");
	}

	@AfterEach
	void tearDown() {
		try {
			if (repository != null) {
				repository.shutDown();
			}
		} finally {
			savedProperties.forEach((name, value) -> {
				if (value == null) {
					System.clearProperty(name);
				} else {
					System.setProperty(name, value);
				}
			});
		}
	}

	private Map<String, Long> open(boolean adjacency) {
		store = new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc").setNativeEvaluationEnabled(true)
				.setDirectAdjacencyEnabled(adjacency));
		repository = new SailRepository(store);
		repository.init();
		Map<String, Long> expected = new LinkedHashMap<>();
		try (SailRepositoryConnection connection = repository.getConnection()) {
			ValueFactory vf = connection.getValueFactory();
			IRI p = vf.createIRI(EX + "p");
			IRI q = vf.createIRI(EX + "q");
			IRI g1 = vf.createIRI(EX + "g1");
			IRI g2 = vf.createIRI(EX + "g2");
			IRI g3 = vf.createIRI(EX + "g3");
			connection.begin();
			for (int i = 0; i < 300; i++) {
				IRI s = vf.createIRI(EX + "s" + i);
				connection.add(s, p, vf.createLiteral(i), g1);
				expected.merge(g1.stringValue(), 1L, Long::sum);
				if (i % 2 == 0) {
					// the same statement in two graphs counts once per graph
					connection.add(s, q, vf.createIRI(EX + "o" + i), g1, g2);
					expected.merge(g1.stringValue(), 1L, Long::sum);
					expected.merge(g2.stringValue(), 1L, Long::sum);
				}
				if (i % 3 == 0) {
					connection.add(s, q, vf.createBNode(), g3);
					expected.merge(g3.stringValue(), 1L, Long::sum);
				}
				// default-graph statements are not named graphs
				connection.add(s, p, vf.createLiteral("default " + i));
			}
			connection.commit();
		}
		if (adjacency) {
			assertThat(AdjacencyEngagementTestAccess.buildNow(store)).isTrue();
		}
		return expected;
	}

	@ParameterizedTest(name = "adjacency={0}")
	@ValueSource(booleans = { true, false })
	void namedGraphCountsComeFromTheContextCatalog(boolean adjacency) {
		Map<String, Long> expected = open(adjacency);
		try (SailRepositoryConnection connection = repository.getConnection()) {
			for (boolean includeInferred : new boolean[] { true, false }) {
				for (String query : List.of(GRAPH_COUNTS, GRAPH_SUBJECT_COUNTS)) {
					assertParity(connection, query, includeInferred);
					assertThat(counts(connection, query, includeInferred))
							.containsExactlyInAnyOrderEntriesOf(expected);
					assertThat(telemetry(connection, query, includeInferred))
							.as("includeInferred=%s adjacency=%s: %s", includeInferred, adjacency, query)
							.contains("nativeExecutionPath=adjacencyCensus", CATALOG, NO_DECODES)
							.doesNotContain(SWEEP);
				}
				assertParity(connection, GRAPH_TOTAL, includeInferred);
				assertThat(telemetry(connection, GRAPH_TOTAL, includeInferred))
						.contains("nativeExecutionPath=adjacencyCensus", CATALOG, NO_DECODES);
				assertParity(connection, NAMED_RESTRICTED, includeInferred);
				assertThat(counts(connection, NAMED_RESTRICTED, includeInferred))
						.containsExactlyInAnyOrderEntriesOf(Map.of(EX + "g2", expected.get(EX + "g2")));
				assertThat(telemetry(connection, NAMED_RESTRICTED, includeInferred)).contains(CATALOG);
			}
		}
	}

	@ParameterizedTest(name = "adjacency={0}")
	@ValueSource(booleans = { true, false })
	void countsFollowTheCurrentSnapshot(boolean adjacency) {
		Map<String, Long> expected = open(adjacency);
		try (SailRepositoryConnection connection = repository.getConnection()) {
			ValueFactory vf = connection.getValueFactory();
			IRI g3 = vf.createIRI(EX + "g3");
			IRI g4 = vf.createIRI(EX + "g4");
			connection.begin();
			connection.remove((IRI) null, null, null, g3);
			connection.add(vf.createIRI(EX + "late"), vf.createIRI(EX + "p"), vf.createLiteral("late"), g4);
			connection.commit();
			expected.remove(g3.stringValue());
			expected.put(g4.stringValue(), 1L);
			if (adjacency) {
				assertThat(AdjacencyEngagementTestAccess.buildNow(store)).isTrue();
			}
			assertParity(connection, GRAPH_COUNTS, true);
			assertThat(counts(connection, GRAPH_COUNTS, true)).containsExactlyInAnyOrderEntriesOf(expected);
			assertThat(telemetry(connection, GRAPH_COUNTS, true)).contains(CATALOG, NO_DECODES);
		}
	}

	/**
	 * With both planes populated the catalog's combined count is exact for neither plane alone, and the composite
	 * explicit+inferred source has no single catalog, so the census keeps its exact page-header sweep.
	 */
	@org.junit.jupiter.api.Test
	void populatedInferredPlaneKeepsThePageSweep() {
		Map<String, Long> expected = open(true);
		try (LmdbStoreConnection connection = (LmdbStoreConnection) store.getConnection()) {
			ValueFactory vf = store.getValueFactory();
			connection.begin();
			connection.addInferredStatement(vf.createIRI(EX + "s0"), vf.createIRI(EX + "p"),
					vf.createLiteral(0), vf.createIRI(EX + "g1"));
			connection.addInferredStatement(vf.createIRI(EX + "inferred"), vf.createIRI(EX + "p"),
					vf.createLiteral("inferred"), vf.createIRI(EX + "inferredGraph"));
			connection.commit();
		}
		assertThat(AdjacencyEngagementTestAccess.buildNow(store)).isTrue();
		Map<String, Long> withInferred = new LinkedHashMap<>(expected);
		withInferred.put(EX + "inferredGraph", 1L);
		try (SailRepositoryConnection connection = repository.getConnection()) {
			assertParity(connection, GRAPH_COUNTS, true);
			assertThat(counts(connection, GRAPH_COUNTS, true)).containsExactlyInAnyOrderEntriesOf(withInferred);
			assertThat(telemetry(connection, GRAPH_COUNTS, true)).doesNotContain(CATALOG);

			assertParity(connection, GRAPH_COUNTS, false);
			assertThat(counts(connection, GRAPH_COUNTS, false)).containsExactlyInAnyOrderEntriesOf(expected);
			assertThat(telemetry(connection, GRAPH_COUNTS, false))
					.contains("nativeExecutionPath=adjacencyCensus", SWEEP)
					.doesNotContain(CATALOG);
		}
	}

	private void assertParity(SailRepositoryConnection connection, String query, boolean includeInferred) {
		System.setProperty(NATIVE, "false");
		List<BindingSet> generic = rows(connection, query, includeInferred);
		System.setProperty(NATIVE, "true");
		assertThat(rows(connection, query, includeInferred)).as("includeInferred=%s: %s", includeInferred, query)
				.containsExactlyInAnyOrderElementsOf(generic);
	}

	private static Map<String, Long> counts(SailRepositoryConnection connection, String query,
			boolean includeInferred) {
		Map<String, Long> counts = new LinkedHashMap<>();
		for (BindingSet row : rows(connection, query, includeInferred)) {
			counts.put(row.getValue("context").stringValue(),
					Long.parseLong(row.getValue("statements").stringValue()));
		}
		return counts;
	}

	private static List<BindingSet> rows(SailRepositoryConnection connection, String query,
			boolean includeInferred) {
		TupleQuery prepared = connection.prepareTupleQuery(query);
		prepared.setIncludeInferred(includeInferred);
		return QueryResults.asList(prepared.evaluate());
	}

	private static String telemetry(SailRepositoryConnection connection, String query, boolean includeInferred) {
		TupleQuery prepared = connection.prepareTupleQuery(query);
		prepared.setIncludeInferred(includeInferred);
		return prepared.explain(Explanation.Level.Telemetry).toString();
	}
}
